  if (!MR)
    return;

  const auto *FR = dyn_cast<FieldRegion>(MR);
  if (!FR)
    return;

  const FieldDecl *CounterFD = nullptr;
  const FieldDecl *FAMFD = nullptr;
  if (!isAssignmentToCounterField(FR, CounterFD, FAMFD))
    return;

  const MemRegion *BaseR = getBaseForFieldOrElement(FR);
  if (!BaseR)
    return;

  (void)S;

  ProgramStateRef State = C.getState();

  // The __counted_by contract is an initialization-ordering relation: once the
  // counter field of the FAM is assigned on this path, later FAM accesses are
  // bounded by that counter (the relation the fix establishes). Only a
  // concretely-zero assignment leaves the counter at its zero-initialized
  // state, keeping the array "not ready"; an unknown symbolic value still
  // counts as an initialized counter.
  bool ConcreteZero = false;
  if (std::optional<nonloc::ConcreteInt> CI = Val.getAs<nonloc::ConcreteInt>())
    ConcreteZero = CI->getValue() == 0;

  if (ConcreteZero)
    State = State->remove<CounterReadyRegions>(BaseR);
  else
    State = State->add<CounterReadyRegions>(BaseR);

  C.addTransition(State);
}

} // end anonymous namespace

